def minPath(grid, k):
    from collections import deque

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start_x, start_y):
        queue = deque([(start_x, start_y, [grid[start_x][start_y]])])
        min_path = None

        while queue:
            x, y, path = queue.popleft()

            if len(path) == k:
                if min_path is None or path < min_path:
                    min_path = path
                continue

            for dx, dy in directions:
                new_x, new_y = x + dx, y + dy
                if 0 <= new_x < n and 0 <= new_y < n:
                    queue.append((new_x, new_y, path + [grid[new_x][new_y]]))

        return min_path

    overall_min_path = None

    for i in range(n):
        for j in range(n):
            current_path = bfs(i, j)
            if current_path is not None:
                if overall_min_path is None or current_path < overall_min_path:
                    overall_min_path = current_path

    return overall_min_path

